const listPublicAccounts = `-- name: ListPublicAccounts :many
SELECT
  accounts.id,
  accounts.system_account_id,
  accounts.name,
  accounts.provider_code,
  accounts.provider_protocol_profile_id,
  accounts.protocol_code,
  accounts.protocol_version,
  accounts.type,
  accounts.status,
  accounts.credentials_encrypted,
  accounts.credential_fingerprint,
  accounts.credential_mask,
  accounts.client_compatibility,
  accounts.health_check_model,
  accounts.health_check_endpoint_mode,
  accounts.schedulable,
  accounts.availability_schedule_json,
  accounts.concurrency_limit,
  accounts.priority,
  accounts.notes,
  accounts.created_at,
  accounts.updated_at,
  groups.id AS bound_group_id,
  groups.name AS bound_group_name
FROM juhe_business.accounts AS accounts
LEFT JOIN juhe_business.group_accounts AS group_accounts
  ON group_accounts.account_id = accounts.id
  AND group_accounts.system_account_id = accounts.system_account_id
LEFT JOIN juhe_business.groups AS groups
  ON groups.id = group_accounts.group_id
  AND groups.system_account_id = group_accounts.system_account_id
WHERE accounts.system_account_id = $1
  AND accounts.deleted_at IS NULL
  AND ($2::text = '' OR accounts.provider_code = $2)
  AND ($3::text = '' OR accounts.provider_protocol_profile_id = $3)
  AND ($4::text = '' OR group_accounts.group_id = $4)
  AND ($5::text = '' OR accounts.type = $5)
  AND ($6::text = '' OR accounts.status = $6)
  AND (
    $7::text = ''
    OR $7::text = 'all'
    OR ($7::text = 'enabled' AND accounts.schedulable = true AND accounts.status = 'active')
    OR ($7::text = 'disabled' AND (accounts.schedulable = false OR accounts.status IN ('pending_test', 'disabled', 'error')))
    OR ($7::text = 'cooling' AND accounts.status IN ('rate_limited', 'temporary_unavailable'))
  )
  AND (
    $8::boolean = false
    OR (accounts.name COLLATE "C" >= $9::text AND accounts.name COLLATE "C" < $10::text)
    OR (accounts.provider_code COLLATE "C" >= $9::text AND accounts.provider_code COLLATE "C" < $10::text)
  )
ORDER BY accounts.updated_at DESC, accounts.created_at DESC, accounts.id DESC
LIMIT $12::int
OFFSET $11::int
`

